exercises.starter_code:
#include <stdio.h>

int main(void) {
    int s[3] = {1, 2, 3};
    // print [1 2 3]
    return 0;
}

exercises.solution:
#include <stdio.h>

int main(void) {
    int s[3] = {1, 2, 3};
    printf("[");
    for (int i = 0; i < 3; i++) {
        if (i) putchar(' ');
        printf("%d", s[i]);
    }
    puts("]");
    return 0;
}

