exercises.starter_code:
#include <stdio.h>

int main(void) {
    int original[] = {1, 2, 3};
    // copy and append
    return 0;
}

exercises.solution:
#include <stdio.h>
#include <string.h>

int main(void) {
    int original[] = {1, 2, 3};
    int copy[4];
    memcpy(copy, original, sizeof original);
    copy[3] = 4;
    printf("[");
    for (int i = 0; i < 3; i++) {
        if (i) putchar(' ');
        printf("%d", original[i]);
    }
    puts("]");
    printf("[");
    for (int i = 0; i < 4; i++) {
        if (i) putchar(' ');
        printf("%d", copy[i]);
    }
    puts("]");
    return 0;
}
